{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Estazolam, the closest analogue by Morgan similarity, has 87% oral bioavailability in healthy volunteers after a single oral dose, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Adinazolam, a structurally related triazolobenzodiazepine, has an absolute oral bioavailability of approximately 40% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam, sharing the chlorophenyl-triazole core, has absolute oral bioavailability generally exceeding 90% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Clobazam, a related benzodiazepine, is rapidly and extensively absorbed with 87–100% bioavailability, and food does not affect its absorption, relevant to the fed-state condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Triazolam, a close triazolobenzodiazepine analogue, has mean oral bioavailability of 55% ± 20% in healthy subjects, above 20% despite intestinal and hepatic first-pass extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Loxapine, a chlorophenyl-substituted tricyclic, has systemic availability of 29%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "One bupropion record reports 10% oral bioavailability, but this is an outlier contradicted by multiple other bupropion records and has low structural similarity to the query; it does not outweigh the consistent high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable physicochemical prior, the transferable experimental evidence from structurally related benzodiazepine-like molecules consistently shows oral bioavailability above 20%, mostly 40–100%. The fed-state condition may further mitigate solubility limitations for this lipophilic compound. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query scaffold.",
    "Morgan similarities to the evidence molecules are low (0.20–0.27), limiting transferability.",
    "The effect of the fed state on this specific molecule's absorption is unknown.",
    "Metabolic stability and transporter-mediated clearance data for the query are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

